export function capturedRecognitionStroke(index: number): number[] {
  const path = PATHS[index];
  if (path === undefined) throw new RangeError("Unknown captured stroke.");
  return path.split(" ").flatMap((pair) => {
    const [x, y] = pair.split(",").map(Number);
    return [x!, y!, 0.5];
  });
}
